pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address target, uint256 value) public {
        vm.assume(caller != c.owner());
        vm.assume(target != address(0));
        vm.assume(value <= address(c).balance);
        uint256 balanceBefore = address(c).balance;
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", target, value));
        vm.assume(!success);
        assertTrue(address(c).balance == balanceBefore);
    }
}

